-- Maintenance procedures for applications, domains, areas, roles, users, and modules.
USE [cxView];
GO

CREATE OR ALTER PROCEDURE dbo.SP_TAS002_CREAR_APLICACION @idempresa varchar(36),@aplicacion varchar(50),@descripcion varchar(200),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; DECLARE @id varchar(36)=CONVERT(varchar(36),NEWID()); INSERT dbo.TAS002(IDAPP,IDEMPRESA,NOMAPP,DESCAPP,ESTAPP,SACRG,CUSCRT,FCHHRACRT) VALUES(@id,LTRIM(RTRIM(@idempresa)),LTRIM(RTRIM(@aplicacion)),NULLIF(LTRIM(RTRIM(@descripcion)),''),'A',1,NULLIF(LTRIM(RTRIM(@usuario)),''),SYSDATETIME()); SELECT * FROM dbo.TAS002 WHERE IDAPP=@id; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS002_ACTUALIZAR_APLICACION @idapp varchar(36),@idempresa varchar(36),@aplicacion varchar(50),@descripcion varchar(200),@estado varchar(1),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS002 SET IDEMPRESA=LTRIM(RTRIM(@idempresa)),NOMAPP=LTRIM(RTRIM(@aplicacion)),DESCAPP=NULLIF(LTRIM(RTRIM(@descripcion)),''),ESTAPP=UPPER(LTRIM(RTRIM(@estado))),CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDAPP=LTRIM(RTRIM(@idapp)) AND SACRG=1; SELECT * FROM dbo.TAS002 WHERE IDAPP=LTRIM(RTRIM(@idapp)) AND SACRG=1; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS002_DAR_BAJA_APLICACION @idapp varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS002 SET ESTAPP='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDAPP=LTRIM(RTRIM(@idapp)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS002_CONSULTAR_APLICACIONES @idapp varchar(36),@idempresa varchar(36),@aplicacion varchar(50),@estado varchar(1) AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.TAS002 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@idapp)),'') IS NULL OR IDAPP=LTRIM(RTRIM(@idapp))) AND (NULLIF(LTRIM(RTRIM(@idempresa)),'') IS NULL OR IDEMPRESA=LTRIM(RTRIM(@idempresa))) AND (NULLIF(LTRIM(RTRIM(@aplicacion)),'') IS NULL OR NOMAPP LIKE '%'+LTRIM(RTRIM(@aplicacion))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTAPP=UPPER(LTRIM(RTRIM(@estado))) ) ORDER BY NOMAPP; END;
GO

