GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS003_DAR_BAJA_DOMINIO @iddominio varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS003 SET ESTDOM='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDDOM=LTRIM(RTRIM(@iddominio)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS003_CONSULTAR_DOMINIOS @iddominio varchar(36),@idempresa varchar(36),@dominio varchar(50),@estado varchar(1) AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.TAS003 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@iddominio)),'') IS NULL OR IDDOM=LTRIM(RTRIM(@iddominio))) AND (NULLIF(LTRIM(RTRIM(@idempresa)),'') IS NULL OR IDEMPRESA=LTRIM(RTRIM(@idempresa))) AND (NULLIF(LTRIM(RTRIM(@dominio)),'') IS NULL OR NOMDOM LIKE '%'+LTRIM(RTRIM(@dominio))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTDOM=UPPER(LTRIM(RTRIM(@estado)))) ORDER BY NOMDOM; END;
GO

