CREATE OR ALTER PROCEDURE dbo.SP_TAS004_DAR_BAJA_AREA @idarea varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS004 SET ESTAREA='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDAREA=LTRIM(RTRIM(@idarea)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
