CREATE OR ALTER PROCEDURE dbo.SP_TAS004_CONSULTAR_AREAS @idarea varchar(36),@idempresa varchar(36),@area varchar(50),@estado varchar(1) AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.TAS004 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@idarea)),'') IS NULL OR IDAREA=LTRIM(RTRIM(@idarea))) AND (NULLIF(LTRIM(RTRIM(@idempresa)),'') IS NULL OR IDEMPRESA=LTRIM(RTRIM(@idempresa))) AND (NULLIF(LTRIM(RTRIM(@area)),'') IS NULL OR NOMAREA LIKE '%'+LTRIM(RTRIM(@area))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTAREA=UPPER(LTRIM(RTRIM(@estado)))) ORDER BY NOMAREA; END;
