CREATE OR ALTER PROCEDURE dbo.SP_TAS005_CREAR_ROL @idarea varchar(36),@rol varchar(50),@descripcion varchar(100),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; DECLARE @id varchar(36)=CONVERT(varchar(36),NEWID()); INSERT dbo.TAS005(IDROLEMP,IDAREA,NOMROL,DESCROL,ESTROL,SACRG,CUSCRT,FCHHRACRT) VALUES(@id,LTRIM(RTRIM(@idarea)),LTRIM(RTRIM(@rol)),NULLIF(LTRIM(RTRIM(@descripcion)),''),'A',1,NULLIF(LTRIM(RTRIM(@usuario)),''),SYSDATETIME()); SELECT * FROM dbo.TAS005 WHERE IDROLEMP=@id; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS005_ACTUALIZAR_ROL @idrol varchar(36),@idarea varchar(36),@rol varchar(50),@descripcion varchar(100),@estado varchar(1),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS005 SET IDAREA=LTRIM(RTRIM(@idarea)),NOMROL=LTRIM(RTRIM(@rol)),DESCROL=NULLIF(LTRIM(RTRIM(@descripcion)),''),ESTROL=UPPER(LTRIM(RTRIM(@estado))),CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDROLEMP=LTRIM(RTRIM(@idrol)) AND SACRG=1; SELECT * FROM dbo.TAS005 WHERE IDROLEMP=LTRIM(RTRIM(@idrol)) AND SACRG=1; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS005_DAR_BAJA_ROL @idrol varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS005 SET ESTROL='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDROLEMP=LTRIM(RTRIM(@idrol)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
