CREATE OR ALTER PROCEDURE dbo.SP_TAS005_CONSULTAR_ROLES @idrol varchar(36),@idarea varchar(36),@rol varchar(50),@estado varchar(1) AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.TAS005 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@idrol)),'') IS NULL OR IDROLEMP=LTRIM(RTRIM(@idrol))) AND (NULLIF(LTRIM(RTRIM(@idarea)),'') IS NULL OR IDAREA=LTRIM(RTRIM(@idarea))) AND (NULLIF(LTRIM(RTRIM(@rol)),'') IS NULL OR NOMROL LIKE '%'+LTRIM(RTRIM(@rol))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTROL=UPPER(LTRIM(RTRIM(@estado)))) ORDER BY NOMROL; END;
