CREATE OR ALTER PROCEDURE dbo.SP_TAS006_CREAR_USUARIO @iddominio varchar(36),@idrol varchar(36),@login varchar(20),@clave varbinary(128),@nombres varchar(50),@apepat varchar(50),@apemat varchar(50),@email varchar(50),@cambiaclave bit,@multiplesedes bit,@sededefecto varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; DECLARE @id varchar(36)=CONVERT(varchar(36),NEWID()); INSERT dbo.TAS006(IDUSER,IDDOMINIO,IDROLEMP,USUARIO,CLAVE,NOMBRES,APEPAT,APEMAT,EMAIL,ESTUSER,FLGACTPASS,FLGMLTSEDE,IDSEDEDEFAULT,SACRG,CUSCRT,FCHHRACRT) VALUES(@id,NULLIF(LTRIM(RTRIM(@iddominio)),''),NULLIF(LTRIM(RTRIM(@idrol)),''),LTRIM(RTRIM(@login)),@clave,NULLIF(LTRIM(RTRIM(@nombres)),''),NULLIF(LTRIM(RTRIM(@apepat)),''),NULLIF(LTRIM(RTRIM(@apemat)),''),NULLIF(LTRIM(RTRIM(@email)),''),'A',COALESCE(@cambiaclave,1),COALESCE(@multiplesedes,0),NULLIF(LTRIM(RTRIM(@sededefecto)),''),1,NULLIF(LTRIM(RTRIM(@usuario)),''),SYSDATETIME()); SELECT IDUSER,IDDOMINIO,IDROLEMP,USUARIO,NOMBRES,APEPAT,APEMAT,EMAIL,ESTUSER,FLGACTPASS,FLGMLTSEDE,IDSEDEDEFAULT,SACRG,CUSCRT,FCHHRACRT,CULUSA,FCHHRAACT FROM dbo.TAS006 WHERE IDUSER=@id; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS006_ACTUALIZAR_USUARIO @iduser varchar(36),@iddominio varchar(36),@idrol varchar(36),@login varchar(20),@clave varbinary(128),@nombres varchar(50),@apepat varchar(50),@apemat varchar(50),@email varchar(50),@estado varchar(1),@cambiaclave bit,@multiplesedes bit,@sededefecto varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS006 SET IDDOMINIO=NULLIF(LTRIM(RTRIM(@iddominio)),''),IDROLEMP=NULLIF(LTRIM(RTRIM(@idrol)),''),USUARIO=LTRIM(RTRIM(@login)),CLAVE=COALESCE(@clave,CLAVE),NOMBRES=NULLIF(LTRIM(RTRIM(@nombres)),''),APEPAT=NULLIF(LTRIM(RTRIM(@apepat)),''),APEMAT=NULLIF(LTRIM(RTRIM(@apemat)),''),EMAIL=NULLIF(LTRIM(RTRIM(@email)),''),ESTUSER=UPPER(LTRIM(RTRIM(@estado))),FLGACTPASS=COALESCE(@cambiaclave,FLGACTPASS),FLGMLTSEDE=COALESCE(@multiplesedes,FLGMLTSEDE),IDSEDEDEFAULT=NULLIF(LTRIM(RTRIM(@sededefecto)),''),CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDUSER=LTRIM(RTRIM(@iduser)) AND SACRG=1; SELECT IDUSER,IDDOMINIO,IDROLEMP,USUARIO,NOMBRES,APEPAT,APEMAT,EMAIL,ESTUSER,FLGACTPASS,FLGMLTSEDE,IDSEDEDEFAULT,SACRG,CUSCRT,FCHHRACRT,CULUSA,FCHHRAACT FROM dbo.TAS006 WHERE IDUSER=LTRIM(RTRIM(@iduser)) AND SACRG=1; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS006_DAR_BAJA_USUARIO @iduser varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS006 SET ESTUSER='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDUSER=LTRIM(RTRIM(@iduser)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS006_CONSULTAR_USUARIOS @iduser varchar(36),@iddominio varchar(36),@idrol varchar(36),@login varchar(20),@email varchar(50),@estado varchar(1) AS BEGIN SET NOCOUNT ON; SELECT IDUSER,IDDOMINIO,IDROLEMP,USUARIO,NOMBRES,APEPAT,APEMAT,EMAIL,ESTUSER,FLGACTPASS,FLGMLTSEDE,IDSEDEDEFAULT,SACRG,CUSCRT,FCHHRACRT,CULUSA,FCHHRAACT FROM dbo.TAS006 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@iduser)),'') IS NULL OR IDUSER=LTRIM(RTRIM(@iduser))) AND (NULLIF(LTRIM(RTRIM(@iddominio)),'') IS NULL OR IDDOMINIO=LTRIM(RTRIM(@iddominio))) AND (NULLIF(LTRIM(RTRIM(@idrol)),'') IS NULL OR IDROLEMP=LTRIM(RTRIM(@idrol))) AND (NULLIF(LTRIM(RTRIM(@login)),'') IS NULL OR USUARIO LIKE '%'+LTRIM(RTRIM(@login))+'%') AND (NULLIF(LTRIM(RTRIM(@email)),'') IS NULL OR EMAIL LIKE '%'+LTRIM(RTRIM(@email))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTUSER=UPPER(LTRIM(RTRIM(@estado)))) ORDER BY USUARIO; END;
GO

CREATE OR ALTER PROCEDURE dbo.SP_TAS007_CREAR_MODULO @idapp varchar(36),@modulo varchar(50),@descripcion varchar(100),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; DECLARE @id varchar(36)=CONVERT(varchar(36),NEWID()); INSERT dbo.TAS007(IDMOD,IDAPP,NOMMOD,DESCMOD,ESTMOD,SACRG,CUSCRT,FCHHRACRT) VALUES(@id,LTRIM(RTRIM(@idapp)),LTRIM(RTRIM(@modulo)),NULLIF(LTRIM(RTRIM(@descripcion)),''),'A',1,NULLIF(LTRIM(RTRIM(@usuario)),''),SYSDATETIME()); SELECT * FROM dbo.TAS007 WHERE IDMOD=@id; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS007_ACTUALIZAR_MODULO @idmodulo varchar(36),@idapp varchar(36),@modulo varchar(50),@descripcion varchar(100),@estado varchar(1),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS007 SET IDAPP=LTRIM(RTRIM(@idapp)),NOMMOD=LTRIM(RTRIM(@modulo)),DESCMOD=NULLIF(LTRIM(RTRIM(@descripcion)),''),ESTMOD=UPPER(LTRIM(RTRIM(@estado))),CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDMOD=LTRIM(RTRIM(@idmodulo)) AND SACRG=1; SELECT * FROM dbo.TAS007 WHERE IDMOD=LTRIM(RTRIM(@idmodulo)) AND SACRG=1; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS007_DAR_BAJA_MODULO @idmodulo varchar(36),@usuario varchar(20) AS BEGIN SET NOCOUNT ON; UPDATE dbo.TAS007 SET ESTMOD='I',SACRG=0,CULUSA=NULLIF(LTRIM(RTRIM(@usuario)),''),FCHHRAACT=SYSDATETIME() WHERE IDMOD=LTRIM(RTRIM(@idmodulo)) AND SACRG=1; SELECT @@ROWCOUNT AS FILASAFECTADAS; END;
GO
CREATE OR ALTER PROCEDURE dbo.SP_TAS007_CONSULTAR_MODULOS @idmodulo varchar(36),@idapp varchar(36),@modulo varchar(50),@estado varchar(1) AS BEGIN SET NOCOUNT ON; SELECT * FROM dbo.TAS007 WHERE SACRG=1 AND (NULLIF(LTRIM(RTRIM(@idmodulo)),'') IS NULL OR IDMOD=LTRIM(RTRIM(@idmodulo))) AND (NULLIF(LTRIM(RTRIM(@idapp)),'') IS NULL OR IDAPP=LTRIM(RTRIM(@idapp))) AND (NULLIF(LTRIM(RTRIM(@modulo)),'') IS NULL OR NOMMOD LIKE '%'+LTRIM(RTRIM(@modulo))+'%') AND (NULLIF(LTRIM(RTRIM(@estado)),'') IS NULL OR ESTMOD=UPPER(LTRIM(RTRIM(@estado)))) ORDER BY NOMMOD; END;
GO
